class ContaAntes {
  private saldo: number;
  readonly titular: string;

  constructor(titular: string, saldo: number) {
    this.titular = titular;
    this.saldo = saldo;
  }

  consultar(): number {
    return this.saldo;
  }
}

// mesma classe, com parameter properties: o modificador no parâmetro
// declara o campo e atribui-o, sem corpo de construtor
class ContaDepois {
  constructor(
    readonly titular: string,
    private saldo: number
  ) {}

  consultar(): number {
    return this.saldo;
  }
}

const antes = new ContaAntes("Ana", 100);
const depois = new ContaDepois("Bruno", 200);
console.log(antes.titular, antes.consultar()); // Ana 100
console.log(depois.titular, depois.consultar()); // Bruno 200

// @ts-expect-error - titular é readonly, mesmo sendo parameter property
depois.titular = "Outro";

class ServicoEmail {
  constructor(
    private readonly chaveApi: string,
    protected readonly remetente: string,
    public readonly ativo: boolean
  ) {}

  enviar(destino: string): string {
    return `de ${this.remetente} para ${destino} (chave ${this.chaveApi})`;
  }
}

class ServicoEmailTransacional extends ServicoEmail {
  remetenteCompleto(): string {
    // protected: acessível aqui porque é uma subclasse
    return `${this.remetente} <transacional>`;
  }
}

const servico = new ServicoEmailTransacional("k-123", "faturas@empresa.pt", true);
console.log(servico.ativo); // true
console.log(servico.remetenteCompleto()); // faturas@empresa.pt <transacional>

// @ts-expect-error - chaveApi é private, não acessível fora da classe onde foi declarada
console.log(servico.chaveApi);

// @ts-expect-error - remetente é protected, não acessível fora da hierarquia
console.log(servico.remetente);

class Temperatura {
  #celsius: number;

  constructor(celsius: number) {
    this.#celsius = celsius;
  }

  get valor(): number {
    return this.#celsius;
  }

  // o setter aceita mais formatos do que o getter devolve
  set valor(novo: string | number) {
    this.#celsius = typeof novo === "string" ? Number.parseFloat(novo) : novo;
  }
}

const t = new Temperatura(20);
t.valor = "25.5";
console.log(t.valor); // 25.5
console.log(typeof t.valor); // number

t.valor = 30;
console.log(t.valor); // 30

class Registo {
  // campo estático: um só valor partilhado por todas as instâncias,
  // tipado como qualquer outro campo
  static totalCriados: number = 0;

  // método estático tipado: parâmetros e retorno seguem as regras habituais
  static resumo(): string {
    return `${Registo.totalCriados} registo(s) criado(s)`;
  }

  constructor(readonly nome: string) {
    Registo.totalCriados += 1;
  }
}

const r1 = new Registo("primeiro");
const r2 = new Registo("segundo");
console.log(Registo.resumo()); // 2 registo(s) criado(s)
console.log(r1.nome, r2.nome); // primeiro segundo

// @ts-expect-error - totalCriados só existe na classe, não nas instâncias
console.log(r1.totalCriados);

class Configuracao {
  static readonly versao: string = "1.0";
  static descricao: string;

  // static initialization block (ES2022): corre uma única vez, quando a
  // classe é avaliada, antes de qualquer instância existir
  static {
    Configuracao.descricao = `Configuracao v${Configuracao.versao}`;
  }
}

console.log(Configuracao.descricao); // Configuracao v1.0

class Falha {
  static readonly limite: number;

  static {
    // @ts-expect-error - um campo static readonly só pode ser atribuído
    // na própria declaração, nunca dentro do static block (TS2540)
    Falha.limite = 100;
  }
}

class ConstrutorConsulta {
  protected partes: string[] = [];

  selecionar(campo: string): this {
    this.partes.push(`SELECT ${campo}`);
    return this;
  }

  de(tabela: string): this {
    this.partes.push(`FROM ${tabela}`);
    return this;
  }

  construir(): string {
    return this.partes.join(" ");
  }
}

class ConstrutorConsultaComFiltro extends ConstrutorConsulta {
  onde(condicao: string): this {
    this.partes.push(`WHERE ${condicao}`);
    return this;
  }
}

const q = new ConstrutorConsultaComFiltro()
  .selecionar("*")
  .de("utilizadores")
  .onde("idade > 18");

console.log(q.construir()); // SELECT * FROM utilizadores WHERE idade > 18

// o tipo anotado confirma que o resultado é a subclasse, não a base:
// onde() só existe em ConstrutorConsultaComFiltro
const verificacaoDeTipo: ConstrutorConsultaComFiltro = new ConstrutorConsultaComFiltro()
  .selecionar("nome")
  .onde("ativo = true");
console.log(verificacaoDeTipo.construir()); // SELECT nome WHERE ativo = true

