class Retangulo {
  constructor(
    readonly largura: number,
    readonly altura: number
  ) {}

  area(): number {
    return this.largura * this.altura;
  }
}

const r = new Retangulo(4, 5);
console.log(r.area()); // 20

// @ts-expect-error - largura é readonly
r.largura = 10;

class Dinheiro {
  #centimos: number = 0;

  set valor(novo: string | number) {
    const euros = typeof novo === "string" ? Number.parseFloat(novo) : novo;
    this.#centimos = Math.round(euros * 100);
  }

  get valor(): number {
    return this.#centimos / 100;
  }
}

const preco = new Dinheiro();
preco.valor = "19.99";
console.log(preco.valor); // 19.99

preco.valor = 5;
console.log(preco.valor); // 5

class Registo {
  static readonly versao: string = "1.0";
  static totalInstancias: number = 0;
  static descricao: string;

  static {
    Registo.descricao = `Registo v${Registo.versao}`;
  }

  private constructor(readonly nome: string) {}

  static criar(nome: string): Registo {
    Registo.totalInstancias += 1;
    return new Registo(nome);
  }
}

const r1 = Registo.criar("primeiro");
const r2 = Registo.criar("segundo");
console.log(r1.nome, r2.nome, Registo.totalInstancias, Registo.descricao);
// primeiro segundo 2 Registo v1.0

// @ts-expect-error - o construtor é private, só a fábrica estática pode criar instâncias
new Registo("direto");

class Notificador {
  protected linhas: string[] = [];

  comAssunto(assunto: string): this {
    this.linhas.push(`Assunto: ${assunto}`);
    return this;
  }

  construir(): string {
    return this.linhas.join(" | ");
  }
}

class NotificadorEmail extends Notificador {
  comAnexo(nome: string): this {
    this.linhas.push(`Anexo: ${nome}`);
    return this;
  }
}

const mensagem: NotificadorEmail = new NotificadorEmail()
  .comAssunto("Fatura")
  .comAnexo("fatura.pdf")
  .comAssunto("Fatura atualizada");

console.log(mensagem.construir());
// Assunto: Fatura | Anexo: fatura.pdf | Assunto: Fatura atualizada
